fun rate_for(score: f64) -> f64 {
    if score > 750.0 { return 3.5 }
    if score > 650.0 { return 5.0 }
    return 7.5
}

pub fun approve(income: f64, debt: f64, score: f64, amount: f64) -> f64 {
    if score < 500.0 { return 0.0 }
    if debt / income > 0.4 { return 0.0 }
    if amount > income * 5.0 { return 0.0 }
    let rate = rate_for(score)
    return amount * rate / 100.0 / 12.0
}
